package com.hengaikj.ai.controller;
import com.hengaikj.ai.entity.ApiKeyEntity; import com.hengaikj.ai.entity.ApiKeySummary; import com.hengaikj.ai.service.ApiKeyService; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.time.Instant;
@RestController @RequestMapping("/internal/api-keys") public class ApiKeyController { private final ApiKeyService service; public ApiKeyController(ApiKeyService s){service=s;} @GetMapping("/verify") public ResponseEntity<String> verify(@RequestHeader String authorization,@RequestParam long enterpriseId,@RequestParam long projectId){if(authorization==null||!authorization.startsWith("Bearer "))return ResponseEntity.status(401).build(); ApiKeyEntity e=service.findActive(authorization.substring(7),enterpriseId,projectId); return e==null?ResponseEntity.status(401).build():ResponseEntity.ok(new ApiKeySummary(e.id,e.keyName,e.keyPrefix,e.status,e.expiresAt,e.createdAt));}}
